const fs = require('bare-fs')
const path = require('bare-path')
const b4a = require('b4a')
const crypto = require('hypercore-crypto')
const id = require('hypercore-id-encoding')
const { create_autodrive } = require('autodrive')
const drive_link = require('drive-link')

module.exports = packs

const DRIVE_PREFIX = 'packs/'

// named autodrives, basims pkg api on top of our vault
// a pack is stored in the vault as packs/<name> = { link, namespace }, link is dat://<key> without a version
// so the name always means the latest files, a pinned link is only made where code runs (pin)
function packs (vault) {
  const { encode, decode } = drive_link()
  const api = { create, list, get, pin, remove }
  return api

  // copy a folder into a new autodrive and save its link under the name (cli only)
  async function create (name, folder) {
    if (await vault.vault_get(`${DRIVE_PREFIX}${name}`)) throw new Error(`pack already exists: ${name}`)
    const namespace = `${DRIVE_PREFIX}${name}/${b4a.toString(crypto.randomBytes(8), 'hex')}`
    const drive = open_drive(namespace)
    await drive.ready()
    for (const file of list_files(folder)) await drive.put(`/${file}`, fs.readFileSync(path.join(folder, file)))
    const link = encode({ key: ['', '', id.normalize(drive.base.key), ''] })
    await drive.close()
    await vault.vault_put(`${DRIVE_PREFIX}${name}`, { link, namespace })
    return link
  }

  async function list () {
    const names = []
    for await (const { key } of vault.get_vault_bee().create_read_stream({ gte: DRIVE_PREFIX, lt: DRIVE_PREFIX.slice(0, -1) + '0' })) names.push(key.slice(DRIVE_PREFIX.length))
    return names
  }

  async function get (name) { return (await vault.vault_get(`${DRIVE_PREFIX}${name}`))?.link || null }

  // the pinned link of a pack right now, for whatever runs its code (bot.json, app deps)
  async function pin (name) {
    const record = await vault.vault_get(`${DRIVE_PREFIX}${name}`)
    if (!record) throw new Error(`unknown pack: ${name}`)
    const drive = open_drive(record.namespace, decode(record.link).key[2])
    await drive.ready()
    const link = await pinned_link(drive)
    await drive.close()
    return link
  }

  // deletes the drive's cores from disk and the name from the vault
  // old view cores from before a device became an indexer are not tracked by autobase, so they stay on disk for now
  async function remove (name) {
    const record = await vault.vault_get(`${DRIVE_PREFIX}${name}`)
    if (!record) throw new Error(`unknown pack: ${name}`)
    const drive = open_drive(record.namespace, decode(record.link).key[2])
    await drive.ready()
    const keys = core_keys(drive.base)
    await drive.close()
    for (const key of keys) await purge(vault.store, key)
    await vault.vault_del(`${DRIVE_PREFIX}${name}`)
  }

  function open_drive (namespace, key) { return create_autodrive({ store: vault.store.namespace(namespace), bootstrap: key ? id.decode(key) : null }) }

  // dat://<signed length>.<fork>.<autobase key>.<hash of the signed files core>
  async function pinned_link (drive) {
    const signed = drive.base.view.drive.core.getBackingCore().session
    while (signed.length < drive.base.view.drive.core.length) {
      await drive.base.update()
      await new Promise(resolve => setTimeout(resolve, 50))
    }
    const hash = b4a.toString(await signed.treeHash(signed.length), 'hex')
    return encode({ key: [signed.length, signed.fork, id.normalize(drive.base.key), hash] })
  }
}

/***************************************
LIST FILES
every file in a folder and its sub folders, as paths relative to the folder
***************************************/
function list_files (folder) {
  return fs.readdirSync(folder, { recursive: true }).filter(file => fs.statSync(path.join(folder, file)).isFile())
}

/***************************************
CORE KEYS
the cores autobase knows about: writers, the system core and the db/blobs views
***************************************/
function core_keys (base) {
  const keys = [base.local.key, base.system.core.getBackingCore().session.key]
  keys.push(base.view.drive.core.getBackingCore().session.key, base.view.drive.blobs.core.getBackingCore().session.key)
  for (const writer of base.activeWriters) keys.push(writer.core.key)
  return [...new Map(keys.map(key => [b4a.toString(key, 'hex'), key])).values()]
}

/***************************************
PURGE
deletes one core from disk if it is stored here
***************************************/
async function purge (store, key) {
  const core = store.get({ key, createIfMissing: false })
  try {
    await core.ready()
    await core.purge()
  } catch {
    await core.close()
  }
}
